CalculateField 无人机禁飞区 zone_id gen_zoneid(!restrict!, !zone_name!) PYTHON3 "# 预先生成分组计数字典，全局存储编号
global count_dict
if "count_dict" not in globals():
    count_dict = {}

def gen_zoneid(restrict, zonename):
    # 1.匹配类型前缀
    if "Controlled Airspace" in restrict:
        pre = "D"
        # 提取三字机场代码 Class D - VNY → VNY
        code = zonename.split("-")[-1].strip()
    elif "VIP" in restrict:
        pre = "VIP"
        code = ""
    elif "Security" in restrict:
        pre = "SEC"
        code = ""
    elif "Large Gathering" in restrict:
        pre = "GAT"
        code = ""
    elif "Stadium" in restrict:
        pre = "STA"
        code = zonename.split()[0]
    elif "Military" in restrict:
        pre = "MIL"
        code = zonename.split()[-2]
    else:
        pre = "OTH"
        code = ""

    key = f"{pre}_{code}"
    if key not in count_dict:
        count_dict[key] = 1
    else:
        count_dict[key] += 1
    seq = f"{count_dict[key]:03d}"

    if code != "":
        return f"{pre}_{code}{seq}"
    else:
        return f"{pre}{seq}"" TEXT NO_ENFORCE_DOMAINS

