CalculateField 无人机禁飞区 zone_id gen_zone_id(!restrict!, !zone_name!) PYTHON3 "global count_dict
if "count_dict" not in globals():
    count_dict = {}

def gen_zone_id(restrict, zonename):
    # 1. 机场管制空域
    if restrict == "Controlled Airspace":
        prefix = "D"
        code = zonename.split("-")[-1].strip()
        key = f"{prefix}_{code}"
    # 2. 各类临时受限空域
    else:
        if zonename == "Vip":
            prefix = "VIP"
            code = ""
            key = prefix
        elif zonename == "Security":
            prefix = "SEC"
            code = ""
            key = prefix
        elif "Large Gathering" in zonename:
            prefix = "GAT"
            code = ""
            key = prefix
        elif "Stadium" in zonename:
            prefix = "STA"
            code = zonename.split()[0]
            key = f"{prefix}_{code}"
        elif "Military" in zonename:
            prefix = "MIL"
            code = zonename.split()[-2]
            key = f"{prefix}_{code}"
        else:
            prefix = "OTH"
            code = ""
            key = prefix
    # 分组自增3位流水号
    if key not in count_dict:
        count_dict[key] = 1
    else:
        count_dict[key] += 1
    seq = f"{count_dict[key]:03d}"
    if code != "":
        return f"{prefix}_{code}{seq}"
    else:
        return f"{prefix}{seq}"" TEXT NO_ENFORCE_DOMAINS
